'use strict';
Object.assign(Business,{
 async allocations(){const [p,a]=await Promise.all([API.request('/plans'),API.request('/allocations')]);this.open('备货管理',`<div class="business-toolbar"><button id="new-plan" class="button primary" ${this.can('allocation:write')?'':'disabled'}>新建销售计划</button><button id="new-allocation" class="button secondary" ${this.can('allocation:write')?'':'disabled'}>选择整捆备货</button></div><a class="button secondary" href="/stock-map?preparation=LOCKED">查看备货锁定地图</a><h3>销售计划（最近300条）</h3><div class="business-table"><table><thead><tr><th>计划号</th><th>客户</th><th>合同号</th><th>目标吨数</th><th>有效锁定吨数</th><th>状态</th><th>操作</th></tr></thead><tbody>${p.items.map(x=>`<tr><td>${esc(x.code)}</td><td>${esc(x.customer_name)}</td><td>${esc(x.contract_no||'历史未关联')}</td><td>${esc(Tonnes.format(x.target_weight))}</td><td>${esc(Tonnes.format(x.locked_weight))}</td><td>${x.status==='OPEN'?'开放':'关闭'}</td><td><button class="detail-button" data-plan-edit="${x.id}" ${this.can('allocation:write')?'':'disabled'}>修改</button></td></tr>`).join('')}</tbody></table></div><h3>备货单（最近300条）</h3><div class="business-table"><table><thead><tr><th>备货单</th><th>计划</th><th>客户</th><th>合同号</th><th>锁定净重（吨）</th><th>装车捆数</th><th>状态</th><th></th></tr></thead><tbody>${a.items.map(x=>`<tr><td>${esc(x.code)}</td><td>${esc(x.plan_code)}</td><td>${esc(x.customer_name)}</td><td>${esc(x.contract_no||'历史未关联')}</td><td>${esc(Tonnes.format(x.locked_weight))}</td><td>${esc(x.loaded_count||0)}</td><td>${{DRAFT:'草稿',LOCKED:'已锁定',RELEASED:'已解除',FULFILLED:'已全部出库'}[x.status]}</td><td><button class="detail-button" data-allocation="${x.id}">详情 / 锁定 / 解除</button></td></tr>`).join('')}</tbody></table></div>`);$('new-plan').onclick=()=>this.planForm().catch(e=>notify(e.message));$('new-allocation').onclick=()=>this.allocationEditor().catch(e=>notify(e.message));document.querySelectorAll('[data-plan-edit]').forEach(b=>b.onclick=()=>this.planForm(p.items.find(x=>x.id===b.dataset.planEdit)).catch(e=>notify(e.message)));document.querySelectorAll('[data-allocation]').forEach(b=>b.onclick=()=>this.allocationDetail(b.dataset.allocation).catch(e=>notify(e.message)));},
 async planForm(p={}){const d=await this.load(),contracts=(await API.request('/contracts')).items;this.open('销售计划',`<form id="plan-form" class="user-form">${p.id?`<p>${esc(p.code)} · 客户与项目不可变更</p>`:`<label>项目<select name="project_id">${this.options(d.projects,null,'name')}</select></label><label>分配客户<select name="customer_id">${this.options(d.customers.filter(c=>c.active),null,'name')}</select></label>`}<label>合同号<select name="contract_id" required ${p.id?'disabled':''}>${contracts.filter(k=>p.id?k.id===p.contract_id:k.validity==='VALID').map(k=>`<option value="${k.id}" data-customer="${k.customer_id}" data-project="${k.project_id}">${esc(k.contract_no+' · '+k.customer_name)}</option>`).join('')}</select></label><label>计划目标净重（吨，最多四位小数）<input name="target_weight" inputmode="decimal" pattern="[0-9]+([.][0-9]{1,4})?" value="${esc(p.target_weight||'')}" required></label>${p.id?`<label>状态<select name="status"><option value="OPEN">开放</option><option value="CLOSED" ${p.status==='CLOSED'?'selected':''}>关闭</option></select></label>`:''}<label>备注<input name="remark" value="${esc(p.remark||'')}" maxlength="500"></label><p id="plan-error" class="error" role="alert"></p><button class="button primary">保存计划</button></form>`);const contractSelect=$('plan-form').elements.contract_id;if(!p.id){const sync=()=>{for(const o of contractSelect.options)o.hidden=o.dataset.customer!==$('plan-form').elements.customer_id.value||o.dataset.project!==$('plan-form').elements.project_id.value;const first=[...contractSelect.options].find(o=>!o.hidden);contractSelect.value=first?.value||'';};$('plan-form').elements.customer_id.onchange=sync;$('plan-form').elements.project_id.onchange=sync;sync();}$('plan-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const body=Object.fromEntries(new FormData(e.target));if(p.id)body.version=p.version;await API.request('/plans'+(p.id?'/'+p.id:''),{method:p.id?'PATCH':'POST',body});await this.allocations();notify('销售计划已保存');}catch(err){$('plan-error').textContent=err.message;e.submitter.disabled=false;}};},
 async allocationEditor(){const [d,p]=await Promise.all([this.load(),API.request('/plans')]);let ids=new Set([...selected]),pageNumber=1,pages=1;this.open('创建客户备货草稿',`<form id="allocation-form" class="user-form"><label>销售计划<select name="plan_id" required>${p.items.filter(x=>x.status==='OPEN'&&x.contract_id).map(x=>`<option value="${x.id}">${esc(x.code+' · '+x.customer_name+' · '+(x.contract_no||'历史未关联')+' · '+x.target_weight+' 吨')}</option>`).join('')}</select></label><label>备注<input name="remark" maxlength="500"></label><p>已带入库存页面的跨页勾选。下方仅列出授权可用捆包；保存草稿不锁定库存。</p><div class="business-toolbar"><label>货权客户<select id="pick-customer"><option value="">全部</option>${d.customers.map(x=>`<option>${esc(x.name)}</option>`).join('')}</select></label><label>批次<select id="pick-batch"><option value="">全部</option>${d.batches.map(x=>`<option>${esc(x.code)}</option>`).join('')}</select></label><label>货位<select id="pick-location"><option value="">全部</option>${d.locations.map(x=>`<option>${esc(x.code)}</option>`).join('')}</select></label><button type="button" id="pick-search" class="button secondary">查询可用库存</button></div><div id="pick-list"></div><div class="business-toolbar"><button id="pick-prev" type="button">上一页</button><span id="pick-page"></span><button id="pick-next" type="button">下一页</button><strong id="pick-count"></strong></div><label>已选捆包编号（每行一捆，可核对或移除）<textarea id="pick-selected" rows="4"></textarea></label><p class="error" id="allocation-error" role="alert"></p><button class="button primary">保存整捆备货草稿</button></form>`);
 const sync=()=>{$('pick-selected').value=[...ids].join('\n');$('pick-count').textContent='已选 '+ids.size+' 捆';};sync();const load=async()=>{try{const rows=await API.request('/inventory?'+new URLSearchParams({status:'在库',customer:$('pick-customer').value,batch:$('pick-batch').value,location:$('pick-location').value,page:pageNumber,page_size:20}));pageNumber=rows.page;pages=Math.max(1,Math.ceil(rows.total/20));$('pick-page').textContent=pageNumber+' / '+pages+' 页 · 共 '+rows.total+' 捆';$('pick-prev').disabled=pageNumber<=1;$('pick-next').disabled=pageNumber>=pages;$('pick-list').innerHTML='<div class="business-table"><table><thead><tr><th>选择</th><th>编号</th><th>批次</th><th>货位</th><th>净重（吨）</th></tr></thead><tbody>'+rows.items.map(x=>`<tr><td><input type="checkbox" data-pick="${esc(x.id)}" ${ids.has(x.id)?'checked':''}></td><td>${esc(x.id)}</td><td>${esc(x.batch)}</td><td>${esc(x.location)}</td><td>${esc(x.weight)}</td></tr>`).join('')+'</tbody></table></div>';document.querySelectorAll('[data-pick]').forEach(x=>x.onchange=()=>{x.checked?ids.add(x.dataset.pick):ids.delete(x.dataset.pick);sync();});}catch(e){$('allocation-error').textContent=e.message;}};$('pick-search').onclick=()=>{pageNumber=1;load();};$('pick-prev').onclick=()=>{pageNumber--;load();};$('pick-next').onclick=()=>{pageNumber++;load();};$('pick-selected').onchange=()=>{ids=new Set($('pick-selected').value.split(/\s+/).filter(Boolean));sync();};await load();$('allocation-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const body=Object.fromEntries(new FormData(e.target));body.bundle_ids=$('pick-selected').value.split(/\s+/).filter(Boolean);const result=await API.request('/allocations',{method:'POST',body});await this.allocationDetail(result.id);notify('草稿已保存，尚未锁定。');}catch(err){$('allocation-error').textContent=err.message;e.submitter.disabled=false;}};},
 async allocationDetail(id){const a=await API.request('/allocations/'+id);this.open('客户备货 '+a.code,`<a class="button secondary" href="/stock-map?${esc(new URLSearchParams({project_id:a.plan.project_id,allocation_id:a.id,preparation:'LOCKED'}))}">在地图查看本单有效锁定货位</a><p>状态：${{DRAFT:'草稿',LOCKED:'已锁定',RELEASED:'已解除',FULFILLED:'已全部出库'}[a.status]} · 计划 ${esc(a.plan.code)} · 合同 ${esc(a.plan.contract_no||'历史未关联')}<br>锁定时间：${esc(a.locked_at||'—')}<br>解除原因：${esc(a.release_reason||'—')}${a.origin==='LEGACY'?'<br>期初历史锁定快照：原操作人/时间未知，不代表迁移时间即原业务时间。':''}</p><div class="business-toolbar">${a.status==='DRAFT'&&this.can('allocation:write')?'<button class="button primary" data-lock-action="lock">正式锁定整单</button>':''}${a.status==='LOCKED'&&this.can('allocation:release')?'<button class="button secondary" data-lock-action="release">解除整单锁定</button>':''}</div><label>解除原因（解除时必填）<input id="release-reason" maxlength="500"></label><p id="lock-error" class="error" role="alert"></p><div class="business-table"><table><thead><tr><th>捆包号</th><th>整捆净重（吨）</th><th>锁定记录</th></tr></thead><tbody>${a.items.map(b=>`<tr><td>${esc(b.bundle_no)}</td><td>${esc(Tonnes.format(b.net_weight))}</td><td>${a.reservations.some(r=>r.bundle_id===b.id&&!r.released_at)?'有效锁定':'无有效锁定'}</td></tr>`).join('')}</tbody></table></div>`);document.querySelectorAll('[data-lock-action]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await API.request('/allocations/'+id+'/'+b.dataset.lockAction,{method:'POST',body:{version:a.version,...(b.dataset.lockAction==='release'?{reason:$('release-reason').value}:{})}});await this.allocationDetail(id);await render();notify('锁定状态已更新，实物库存未减少。');}catch(err){$('lock-error').textContent=err.message;b.disabled=false;}});}
});
const allocationNav=document.createElement('button');allocationNav.dataset.legacyMain='preparation';allocationNav.textContent='▣ 客户备货';allocationNav.onclick=()=>Business.allocations().catch(e=>notify(e.message));document.querySelector('.sidebar nav').append(allocationNav);
